commands:
if (-not ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltinRole] "Administrator")) {
  Start-Process powershell "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
  exit
 }

 Get-Process -Name "Streamlabs" -ErrorAction SilentlyContinue | Stop-Process -Force

 $StartupPath = "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup"
 $StreamlabsStartup = Join-Path $StartupPath "Streamlabs.lnk"
 if (Test-Path $StreamlabsStartup) { Remove-Item $StreamlabsStartup -Force }

 $Tasks = @(
  "\StreamlabsUpdate",
  "\StreamlabsTelemetry"
 )
 foreach ($Task in $Tasks) {
  if (Get-ScheduledTask -TaskPath "\" -TaskName $Task -ErrorAction SilentlyContinue) {
  Disable-ScheduledTask -TaskName $Task -TaskPath "\" -ErrorAction SilentlyContinue
  Unregister-ScheduledTask -TaskName $Task -TaskPath "\" -Confirm:$false -ErrorAction SilentlyContinue
  }
 }

 $ServiceName = "StreamlabsUpdateService"
 if (Get-Service -Name $ServiceName -ErrorAction SilentlyContinue) {
  Stop-Service -Name $ServiceName -Force -ErrorAction SilentlyContinue
  Set-Service -Name $ServiceName -StartupType Disabled -ErrorAction SilentlyContinue
 }

 $AppDataPath = "$env:APPDATA\Streamlabs"
 if (Test-Path $AppDataPath) { Remove-Item $AppDataPath -Recurse -Force -ErrorAction SilentlyContinue }

 $LocalAppDataPath = "$env:LOCALAPPDATA\Streamlabs"
 if (Test-Path $LocalAppDataPath) { Remove-Item $LocalAppDataPath -Recurse -Force -ErrorAction SilentlyContinue }

 $RegistryPaths = @(
  "HKCU:\Software\Streamlabs\Telemetry",
  "HKCU:\Software\Streamlabs\Update",
  "HKLM:\Software\Streamlabs\Telemetry",
  "HKLM:\Software\Streamlabs\Update"
 )
 foreach ($RegPath in $RegistryPaths) {
  if (Test-Path $RegPath) { Remove-Item -Path $RegPath -Recurse -Force -ErrorAction SilentlyContinue }
 }
